package com.savora.security; import com.savora.repo.UserRepo; import jakarta.servlet.*; import jakarta.servlet.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.authority.SimpleGrantedAuthority; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Component; import org.springframework.web.filter.OncePerRequestFilter; import java.io.*; import java.util.*;
@Component public class JwtFilter extends OncePerRequestFilter { final JwtService jwt; final UserRepo users; public JwtFilter(JwtService j,UserRepo u){jwt=j;users=u;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException {String h=r.getHeader("Authorization");if(h!=null&&h.startsWith("Bearer "))try{var u=users.findByEmail(jwt.email(h.substring(7))).orElse(null);if(u!=null)SecurityContextHolder.getContext().setAuthentication(new UsernamePasswordAuthenticationToken(u.email,null,List.of(new SimpleGrantedAuthority("ROLE_"+u.role))));}catch(Exception e){} c.doFilter(r,s);} }
